import React, { Component } from "react";
import {
  Button,
  Modal,
  ModalHeader,
  ModalBody,
  Form,
  FormGroup,
  Label,
  Input,
  NavLink
} from "reactstrap";
import { connect } from "react-redux";
import PropTypes from "prop-types";

class RegisterModal extends Component {
  state = {
    modal: false,
    name: "",
    email: "",
    password: "",
    msg: null
  };
  static propTypes = {
    isAutheticated: PropTypes.bool,
    error: PropTypes.object.isRequired
  };
  toggle = () => {
    this.setState({
      modal: !this.state.modal
    });
  };
  onSubmit = e => {
    e.preventDefault();

    this.toggle();
  };
  onChange = e => {
    this.setState({ [e.target.name]: e.target.value });
  };

  render() {
    return (
      <div>
        <NavLink onClick={this.toggle} href="#">
          Register
        </NavLink>
        <Modal isOpen={this.state.modal} toggle={this.toggle}>
          <ModalHeader toggle={this.toggle}>Register</ModalHeader>
          <ModalBody>
            <Form onSubmit={this.onSubmit}>
              <FormGroup>
                <Label for="name">Name</Label>
                <Input
                  type="text"
                  name="name" //has to match the name of the variable in the state
                  id="item"
                  placeholder="Name"
                  onChange={this.onChange}
                  className="mb-3"
                />
                <Label for="email">Email</Label>
                <Input
                  type="email"
                  name="email" //has to match the name of the variable in the state
                  id="email"
                  placeholder="Email"
                  onChange={this.onChange}
                  style={{ marginBottom: "2rem" }}
                />
                <Label for="password">Password</Label>
                <Input
                  type="password"
                  name="password" //has to match the name of the variable in the state
                  id="password"
                  placeholder="Password"
                  onChange={this.onChange}
                  style={{ marginBottom: "2rem" }}
                />
                <Label for="password2">Re-type Password</Label>
                <Input
                  type="password"
                  name="password2" //has to match the name of the variable in the state
                  id="password2"
                  placeholder="Password"
                  onChange={this.onChange}
                  style={{ marginBottom: "2rem" }}
                />
                <Button color="dark" style={{ marginBottom: "2rem" }} block>
                  Register
                </Button>
              </FormGroup>
            </Form>
          </ModalBody>
        </Modal>
      </div>
    );
  }
}

const mapStateToProps = state => ({
  isAutheticated: state.auth.isAutheticated,
  error: state.error
});

export default connect(mapStateToProps, {})(RegisterModal);
